        "出处：`docs/operations/context-hooks.md`、`tools/Invoke-ClaudeRootHooks.ps1`、`tools/codex_context_install.py`、`tools/claude_root_runtime.py`、`tools/codex_context_hook.py`、`docs/contracts/agents.antigravity-adapter.md`"
