      "imageText": "我说过的话一字不改存着，要核实时按编号取\n我在 Claude、Codex、Antigravity 里亲手打的每一句，都按它自带的编号原样存一份，一条不漏也不重；程序塞进对话的提醒、派给别的 AI 的单子、自动接着干的话都不收。怎么做到的在〔原话存档〕。\n平时 AI 不翻这些旧话：开对话、压缩以后都不再把以前的原话递给它；它照这件工程的《他要什么》和定下的稿子干活，我新说的话优先。\n只有几种时候才按编号把原话取出来：核实一句话到底是不是我说的；要把我的话原样转出去；AI 改规矩放宽了限制，或者要给工期加时间，都得指着我点头的那条消息。\nAI 转述我的话，只算它的理解；照着原话做错了，也算它没听懂。查不到原话，不等于我没说过。"
