      "imageText": "AI 报的工期，要记在账上认\nAI 一开工就报一个施工时间，写进账本。这个数一直留着；后来再怎么变，只能另报一个“现预计”，抹不掉原来的承诺。\n想加时间，得拿出开工以后我真说过的那句加需求的原话，对得上才算；空说一句“需求变了”，加不了一分钟。\n对话停着、等我回话、登记过的等待，都自动从施工时间里扣掉；派出去的 AI 还在干活，照样算施工。\n每一步该给多少分钟，是从自己做完的活里学出来的；记录还不够时，明说先用的是事先定好的起步数。交付时逐步对账，写清每次偏差为什么；样本够了，还查它是不是总往一边偏。\n新活开工时，同一对话和别的对话里没交付的旧活一起列出来，不让新活把旧活盖过去。"
