      "imageText": "派出去的活，断了在原处接着做，交回来还得验\n主持的 AI 把一件活派给别的 AI（接活的那个叫子代理），单子上只写要得到什么、边界在哪，怎么做由接活的自己查、自己定。\n派出去以后，主持退出了，活照样在做；网断了、AI 那边忙不过来，就在原来那条线上等一等接着做；接活的 AI 不见了，能找回原来那条线，已做的一点不丢，也不重开一份。\n交回来的东西，接活的要按真实用法自己跑一遍、交回原样结果，自称做好了不算；主持看结果收单，不重跑同一套。断了怎么接、到点怎么叫醒主持、怎么验，都在〔派出去的活〕。\n派给谁、用哪一档，三家 AI 照同一张分工清单选：成片的活直接交 GPT 的 Sol 牵头拆单、施工、验收，只有选错要推倒重来、坏了撤不回这类难事，才先请 Astra 定做法；一家额度用完、账号用不了，照清单换另一家接着做，并告诉我。新模型出来以后，〔新模型摸底〕查清它擅长什么、各类活该派它哪一档。"
