      "imageText": "网页先画出来，再定哪几处才写代码\n要静态画面，AI 直接交给画图模型画、改：插画、封面、带字的说明图，换字、换背景、抠图，都让它直接做。\n做网页、做视频，也先出一张图拿到样子。再一块一块定：哪几处直接用生成的图，哪几处才写代码；只有会变的数字、动画、要点一下才有反应的地方、手机上要重排的地方，才值得写。按钮可以画在图里，上面盖一块透明的、能点的区域。\n要复用就把旧图传进去，只说要改的地方。我认可的那张定下来不再改，后面整套图都拿它当参考，一整套的风格就拴在这一张上。"
