      "imageText": "几件活同时干：不抢同一个地方，也不把电脑拖死\n要占很多内存的重活，比如把代码做成程序、开浏览器跑检查，不定死同时只准跑几个，而是看电脑眼下实际还剩多少内存：不够就等一等，够了马上开工。\n发规则、装软件、改定时程序（到点自己运行的程序，Windows 里叫“计划任务”）这类同一时刻只能一个人做的事，先领一把短锁，做完就放开；做的人失联了，锁到期别人就能接手，不会一直卡着后面的人。"
