      "imageText": "技能装到各家 AI 手边：装好了，不等于真能用\n每门技能的说明只存一份原件。各家 AI 找技能时，看到的是指向这份原件的“快捷方式”，不是复制品：原件一改，各家 AI 下次读到的就是新的；停用一门技能，只删快捷方式，原件不动。\n有个坑很难想到：AI 干活时常临时复制一份代码来改，用完就收掉。要是从这种临时复制品里装技能，当时一切正常，过几天复制品一收，技能就悄悄失效了。所以安装程序一认出是临时复制品，就拒绝安装。\n查一个技能时，分开报三件事：原件完好吗、快捷方式指对了吗、在一次新对话里真用起来过吗。没核实的就明说没核实，不冒充通过。"
