      "imageText": "放松一句限制，要对上我的原话\n每发一版新规矩，程序把新旧两版一句一句对：旧版里的限制句，到新版里变了样或不见了的，全部列出来。\n列出来的一次交给另一个 AI 逐条判：意思没变、变了，还是拿不准。限制管的事变少了、条件放宽了、例外变多了、口气变软了、准 AI 自己办的事变多了，哪一样都不算没变。判“没变”的，还要从新版里抄出对应的那句，程序核实这句真在新版里。\n真放宽了的，必须指向我的一条原话：要么那句话本来就在说改规则、改约法；要么逐处比对改动合不合我那句话的本意，每一处都要拿出我原话里的逐字依据。\n这条原话再核两遍：〔原话存档〕把我对三家 AI 说的每句话都原样存了一份，先看存档里记着是我发的；再回到 AI 工具自己的原始对话记录里，找到同一条消息，一字不差。存档里写着“同意”、原始记录里没有，不算。\n开场那一页约法和三家入口，改一个字都要对上我点过头的那条消息。\n哪一环对不上，都不放行。"
