      "imageText": "新的一句怎么写进来\n先找原句：讲同一件事的已经有了，就改那一句；同一件事写在几处的，几处一起改。没有才补一句，不往后堆。\n放在哪一层：写到 AI 做那件事时一定读得到的地方。要是没把握，先放在说这句话的那个项目里：放窄了，别的项目顶多出一次同样的错、我再说一次；放宽了，所有项目都会被误伤。要是在其他地方也碰上了，或者我说了“以后都”，再往上挪。\n两家各读一遍：同一句话，两家读出来宽窄不一样。Codex 用的 GPT 往严了读，“别……”和门槛会被放大，要它做的事得正面写出来；Claude 往宽了读，例外和“可以”会被放大，例外要写窄。共用的句子按两种读法各过一遍，只治一家的，写进那家入口自己的结尾。\n只写现在的结论：规矩里不抄我的原话，只写现在要怎么做，附上那句话的时间和消息编号，原话本身留在〔原话存档〕。一句原话只说明我当时这样说过，不证明事情确实如此，也不证明现在还这样要。发布前程序还会扫一遍，抄进规矩里的原话发不出去。"
