      "imageText": "动笔那一下，先查打不打架\n只在 AI 真要写规矩文件的那一下提醒：约法、两家入口、各个专题。换着法子写都认得出来，只是读一读、搜一搜不提醒。提醒不挡事，也不一遍遍重复。提醒由〔规矩落地〕递过来，它在 AI 干活的每个要紧当口把该守的规矩递到眼前。\n提醒它两件事：先查打不打架；约法和两家入口的句子先给我看，我点头才发，它自己另加的要求、新程序、改了适用范围的也一样。\n查打架：另派一个没看过这句、也不知道为什么改、谁要改的 AI，拿改前改后、约法全文和讲同一件事的专题，只报四样：和哪句说法相反；和哪句重复；哪个词在别处指的是另一样东西、哪个指代找不到了；新句本身站不站得住，做不做得到、和事实对不对得上。\n查出来怎么改，由写这句的 AI 定。"
