      "imageText": "每个要紧当口，都有程序接住\n规矩写得再好，AI 干着干着也会忘。Claude、Codex 干活时有几个固定的当口，允许外面挂上程序插一句话（这种程序叫钩子）。我在每个当口都挂了一个：\n开场、接着旧对话时：核对它读到的是不是正在用的那一版规矩。\n收到我的话时：告诉它现在的北京时间、它是哪个模型和档位、私人资料锁着没有、我给过的授权还在不在；我连发了几条，就列成清单。\n动用工具之前：危险的、不该它做的，当场拦下，或者改好再放行。\n工具用完以后：提醒还没跑的验收；问到值不值、好不好用这类事，提醒它先去查真人怎么说（〔四处打听〕）。\n想收工时：只查三样：被私人资料锁挡住的事处理了没有、派出去的活有没有人守着、给我的回复是不是成了英文。\n压缩前后（对话太长时，AI 会把前面压成一段摘要）：提前预警；压缩完告诉它这件活在哪个工程、《他要什么》在哪，先读再接着做。\n顺带：磁盘快满、电脑的健康状况亮了红灯，提醒一次；两家共用一本账，同一件事不重复说。\n这些程序自己出了错，只当这一项没查成：不吞掉我刚发的话，也不把对话卡住。"
