        "不逼它重说：收工时不会因为清单，要它把整段回复再写一遍。",
        "说中文：Claude 回给我的话主要成了英文，收工前拦一次，改回中文；中途冒出一段英文说明，提醒它下一句用中文补上意思。代码、网址、文件名里的英文不算。",
        "出处：`tools/claude_root_runtime.py`（消息清单、北京时间、中文和长回复提醒）、`tools/codex_context_hook.py`"
