      "imageText": "AI 问我的那句话，没看到也丢不了\nAI 收工时常在最后问我一句：选哪个、要不要接着做。我要是没看到，这件事就一直悬着，它也只能干等。\n程序不替它乱记，只把“这里有一问还没答”递给 AI：这一轮当面问过、我会回的不用记；我这一轮没回、或者要以后才办的，由 AI 判断写进实况（我网站上的一页状态页，汇总电脑现在好不好、有哪些事等我办）的“等你的事”，写清要我选什么、选了会怎样、它建议哪个。\n我后来在同一个对话里回了话，程序把原来那件事和我这条消息一起递回给 AI。它先认领，核对我答的是哪一件、照着办完，才关掉那一条；我没答到的，照样挂着。\n已经用别的办法摆到我眼前的，不重复递。\n到点自己开工的 AI 任务收了工却没交结论，程序拿它收尾时那段小结的头一句替它补交。"
