        "删除保护管到哪：只改看得清的简单删除命令；查说明、查版本的不改，PowerShell（Windows 自带的另一种命令窗口）的不改；认不出就放行，不装作每条命令都看懂了。",
        "自带浏览器也一样：Claude 自带的浏览器和伸进 Chrome 的插件同一个放行条件，看本机网页也不例外。",
