        "每样都注明来源：告诉它型号和档位时，写明是 AI 工具给的还是对话设置里读的；两样都不知道，就干脆不写这一行。",
        "继承的不重复塞：Codex 的子代理开工时，已经从主持那里带过来的那几行状态（型号、私人资料锁着没有、它属于哪个对话），一样的就不再塞一遍，省得重复的话把它淹了；证明不了是带过来的，全部照给。",
        "配对消息编号：Codex 的提醒照常先递上；真要动用私人资料时，再核对它对应的确实是我这一轮的那条消息，配不上就不认，不拿旧编号顶。",
        "出处：`tools/claude_root_runtime.py`、`tools/codex_context_hook.py`、`tools/codex_host_binding.py`、`tests/test_codex_host_binding.py`"
