        "三家都能当主持：Claude、Codex、Antigravity 派给自家的 AI，用各自本身就带的派子代理功能；派给别家的，都走这一页讲的这一套，GPT、Claude、Antigravity 背后的 Gemini 都派得出去，单子上每次写明型号和档位。",
        "**一单活怎么走**",
        "九步：从写单子到收拾干净，后面几张图各细讲其中一段。",
        "1. 写单子：写清要什么、什么不能动、最多写多少代码、给多少分钟。",
        "2. 派出去：交给一个独立的程序带着跑，主持手上不用一直攥着。",
        "3. 等着看：一次盯住全部在跑的单子，只看新的进展。",
        "4. 半路纠正：子代理从接到单子到交回这一次结果，叫一轮；一句纠正送进它正在做的这一轮，看得到它听进去没有。",
