      "height": 887,
      "detail": [
        "进度只读新的：看进度只读上次之后新写的，最多 6 条、合计 900 字；读的时候不占住文件，不妨碍子代理接着写。",
        "多久算没长：取时限的八分之一，最短 10 分钟、最长 30 分钟。",
        "平时看一行：每单的状态平时只给一行简短的，要细查再打开完整记录。",
        "看进度出错不打断：看进度是旁务，这一步出了错只留记录，不打断已经跑了几个小时的活。",
        "没写成果放哪：这样的单子 30 分钟没有任何动静就叫醒主持；一直在重试的，每 15 分钟叫一次。",
        "长输出压着存：子代理跑命令时会打出大段文字（结果、报错这类），在运行记录里压缩着存，要看时一字不差能还原，记录不会被重复的大段文字撑大。",
        "往下派有上限：三家派出去的子代理都可以在自己那一单的范围和授权里再派一层，到孙代理为止，孙代理不能再派；单子写明不许再派的，一层也不派。主持叫停一单，它手下还在跑的那几单一起停。",
        "读私人资料的单子：子代理要读私人资料（短信、聊天、照片、证件这类只属于自己的东西）时，主持能看到的只有它写进指定那一份摘录文件的内容；那份摘录没按时写好，主持只看到一句通用状态，看不到子代理的原始报告和它读到的原文。",
        "出处：`tools/claude-gpt-child-lifecycle.ps1`、`tools/Get-GptChildDigest.ps1`、`tools/claude-gpt-child-app-server.mjs`、`tools/claude-gpt-child-event-log.mjs`、`tools/Invoke-ClaudeGptChild.ps1`（往下派的层数、叫停连带下层）、`docs/claude-gpt-child-dispatch.md`、`docs/contracts/agents.execution-coordination.md`“派子代理的原则”。"
      ],
      "buttons": [],
      "imageText": "一次盯住一批活，不被三种假象骗\n主持派出去好几单时，一次等候就盯住全部：哪一单先结束就先叫醒主持，同时把其他几单的新进展一起带回来。这一次等候能连着盯上好几个小时，中间没有一刻没人看着；叫醒的理由各算各的，同一件事不重复叫。\n程序开着，不等于在干活。单子可以写明成果放在哪、要出几个；文件个数和大小有一阵子都没长，就叫醒主持一次，长了再停才再叫。\n运行记录安静，不等于停了。只要成果还在长，就不当它卡住。\n手下交了卷，不等于它交了卷。子代理自己也会再派人；程序只认主持派出的那一单，手下的人先交了卷，不会被当成这一单做完了。\n同一种错反复出，就叫主持来看；同一条命令反复跑、接连失败，也会标出来。"
