        "出处：`docs/claude-gpt-child-dispatch.md`（Claude 验收那几段）、`tools/Invoke-ClaudeGptChild.ps1`（`RecordClaudeAcceptance`）、`tools/claude_root_runtime.py`、`skills/dispatch-work/SKILL.md`。"
