      "imageText": "要换一家 AI 才验得了的，记成清单交给 Claude 验\nCodex 当主持时派出去的活，有些改动的效果要在 Claude 里亲自用一遍才看得出来，Codex 那边验不了。改到 Claude 那一侧的东西时，Codex 收尾会提醒一句，由 AI 判断要不要登记；要登记的，子代理交活前把这些检查一条条原样写进一张待验清单。\nClaude 读到这件活的回执时，会被提醒一次：还有几条得在它这边跑。它照清单派一个子代理逐条跑，看输出和报告，不只看有没有报错；每一条都要留下真跑出来的证据，写明跑的哪条命令、证据在哪、几点看到的。\n条条有证据、条条都过，才正式签收；缺证据或没过的，照样留在清单上等着跑。签收以后，正式验收直接用这批检查，不再重跑一遍。"
