      "imageText": "开工报的数不许改，只有我说的话才能加时间\nAI 报的工期一超，最顺手的说法就是“需求变了”“比想的复杂”。所以开工时报的那个数一直留在账上，谁也改不了，过了它就是延期。\n要加时间只有一条路：拿出我开工以后说的那句话。程序去原话存档里找那一条（我对 AI 说的每句话都原样存着一份，见〔原话存档〕），确实是我开工后说的才让加。加上了，当场那一行写明“我几点说的‘……’，加多少分钟，总预计从多少变成多少”。分不清是我加的还是 AI 原来漏想的，算 AI 的，不加时间。\n做着发现剩下的活比想的大或小，AI 另报一个“现预计”：已经干了多少，加上剩下的按记录还要多少。开工报的数照旧留着，延期照旧按它算：能改原来的数，就永远不会有延期；原来的数和实际差多少，正是下次估得更准的依据。\n现预计一再往后推，程序就提醒 AI 说清是做法不行还是偶然出事，请我在换做法、缩范围、停手里选一个。"
