      "imageText": "AI 认出这次特殊在哪，记录定下要几分钟\nAI 看得懂这件活是什么、哪里特殊，对“要多少分钟”却没有感觉；记录知道每类事实际要多久，却看不懂这一件。所以两边分工。\nAI 只花几分钟判断：拆成几步，哪几步能同时做；每步大还是小；这次有哪些特殊情况，比如“两张单改同一个文件”。\n分钟数全由记录定。派给别的 AI 的每张单子（派出去怎么盯、怎么验，见〔派出去的活〕），看同一种模型干同一类活最近实际用了多久；记录还少时先用起步数。特殊情况也从记录里学：勾过它的活比什么都没勾的活多花多少，就是它的分量；没用的学下来接近零，就不再列。程序几秒钟出一张估时卡片，每一步几分钟、凭几次记录都写在上面，没记录的明写“先这样”。\n记录按步骤记、不按需求记，所以从没做过的新需求，拆开以后也有现成的分量。"
