      "imageText": "停着不算，干着才算\n从开工到交付，常有大段时间 AI 根本没在干活：在等我回话，对话停着，或者在等别的事。程序翻这次对话的记录，自己把这些时间找出来扣掉。\nAI 回完话、或者我按了停止，就算停着，直到我再发话或它被叫醒。可它派出去的子代理（一个 AI 把一部分活交给另一个 AI 去做，接活的那个叫子代理）还在跑，这段就照算施工；只挂着个后台小程序、没有 AI 在动手的，不算。\n程序看不见的等，比如一轮里断了网、在等别的对话，由 AI 自己填分钟、写一句原因。交付那一行写明扣了停着的多少分钟，其中等我回话多少。\n完工只认 AI 宣布做完的那一刻，不能往前填。"
