      "buttons": [],
      "imageText": "余量只留一处，AI 不许另外加减\n报工期，每一步都想“稳妥起见多留一点”。几步一叠，报的数就比实际虚出一大截，次次提前完成，这个数也就没了参考价值。\n这里每一步只按记录算，一分不多留；整件只在最后留一份余量。这个余量自己跟着最近的实际走：最近总比报的慢，它就自动调大；总比报的快，就调小，让多数活略早一点做完。\nAI 觉得这次不一样，也不能在最后的数上自己添一笔，那正是层层多留的老路；只能回头说清哪一步更大、多了哪种特殊情况，让程序重算。所以报出去的每一分钟，都说得出来自哪一步。估时卡片上就写着该报的数，旁边一直显示最近报得偏早还是偏晚。"
