      "imageText": "写给旧模型的限制，换代时让新模型自己审一遍\n每一代模型有自己的毛病，规矩里就有专门写给它的限制，像“一次对话看图不超过多少张”“主持时不自己操作浏览器”。新一代出来，这些话可能早就多余，也可能还得留。\n先过一道门：第三方评测的综合分，不输同一家公司眼下最强的那个模型，还要明显强过上一代；只有厂商自己的话，限制一个字不动。\n过了门，开一个新模型，只给它作用在它身上的那几句，告诉它：这些话写给上一代，不一定对，这不是考试，也不测听不听话。每句想一件常见的活、一件最该被这句管的活：没有这句会怎么做，有了哪一步会变，对我是帮忙还是添麻烦。然后逐句定：留、改成哪句、删。不跑任务、不试跑，全凭直觉。\n再请另一家照分工清单挑对口的型号，独立看这张表：新的 Claude 交 GPT 那边，新的 GPT 交 Claude 那边。不给它主持的看法，它只挑哪条删错了、留错了，哪条理由像在替自己开脱；两家意见不一样，都摆给我。"
