      "imageText": "放开一条限制，改在真管事的地方，只对这一代算数\n分工清单里有一张限制表，记着每条限制管哪个型号、为什么。可它只是索引。像“看图要分批”这一条，真管事的写在好几份说明里，还有一段程序专门拦着。要放开它，这几处都得改；只在表上划掉，AI 照样被拦。\n改动只作用于审它的这个型号和它的后代，别的型号、别家一概不动：它变强了，不能顺手宣布别家的毛病也好了。几个型号共用的一句不删，只标明从这一代起不算。\n删掉的行不抹，写清哪一代删的、为什么。下一代过门再审时，连前代删过的一起读，觉得删错了可以提出恢复。\n放开要我点头才算：改规矩照〔一本规矩〕发布，它让规矩只在一处改、各家 AI 读同一版，放宽一句要对得上我的原话。没点头的，表里记“待定”，照旧拦着。"
