        "要惊艳的看成品：几份成品摆在一起、不告诉评的人是谁做的，让真人挑；再看网页设计的真人投票榜，不只看编程分。",
        "表不是不用想的默认：分工表写的是最常见情况的答案；每一单先看这件活本身要不要派、派谁、多深，和表上不一样就照这件活定。",
