        "出处：`skills/model-research/SKILL.md`“新型号怎么调研”第 3、6 步；`config/model-roster.json` 的 `routing.tiers`、`routing.effort_rule`、`routing.scenarios`、`routing.current_generation_defaults`；`docs/research/2026-10-29-aa-v5-models.md`“ToneBench全量重跑后的完整已测分档”“关键对照、缺口与推断”；`docs/research/2026-11-18-gpt-6.2.md`"
