      "imageText": "分数对齐了才比，不被排行榜骗\n先弄清每项评测量的是什么：题长什么样、分数怎么算、对应我哪类活。有一项测故障诊断的，只测找原因、不测修好；看图推理分高，不证明审美好，也不证明能找全图里的错字。分数是在很难的题上比高低，不是日常干活的成功率。\n再对齐四样：评测是哪一版、哪个型号、实际开的哪一档、在什么环境里跑。评测改了版，新旧总分不能比；有一项把题目从六千道减到三千道，分数降了不算退步。综合排行榜和专看 AI 自己动手改代码的那张榜，跑法不同，拼不成一张表。\n最高档的分不能替低档作证；缺的数就空着，不拿别的来补。\n实在比不了的那一项就照旧，不让我替 AI 读榜。\n强不强只认厂商公布的数和第三方评测，不在电脑上拿几道题试跑；派不派得出、实际是哪个型号、多慢、会不会卡住，照实际用下来的记录。"
