        "还没核实的：Antigravity 自带的子代理选的是“pro”“flash”这类大类，各对应哪款 Gemini，Google 没写明，等本机实测。",
        "背后的几样：规矩发布前那两道逐处比对（改写以后旧限制还在不在、放宽的地方合不合我原话的本意）；两台电脑上到点自己叫 AI 干活的后台任务，比如每周规矩复核。换代时这些后台任务逐个核一遍，型号和档位写死在程序里的，当场改成从这张清单取。",
        "我的另一个项目〔AI 发射台〕：选好工具、模型和账号就启动原版 AI 工具的启动器，启动时也照这同一份登记换成现在的型号。",
        "**换代时怎么改**",
