      "imageText": "清单改了不算完，真派出去的那一下也得是新的\n换代以后挨个入口落实。派活那一下，写着旧名字的请求当场换成现在的型号，记下原来要的是什么、为什么换。〔规矩落地〕在 AI 干活的每个要紧当口把该守的递到它眼前，这一步也由它在动手前接住。\n改完不算数，只看过程序的代码、跑过模拟测试也不算：要真派一次，核对接活的 AI 系统里写的到底是哪个型号。各项目、各技能里直接写着型号名的地方，一并对一遍。\n主持自己埋头动手太久，会有提醒叫它把活交出去；换了分工，这道提醒也跟新分工对上。\n已经派出去、干到一半的旧子代理换不了型号，就把剩下的活交给新型号接着办。〔派出去的活〕管的就是这一整套：派出去的活断了在原处接上，做完验过才交。"
