      "buttons": [],
      "imageText": "该问的当场问，不该问的不来烦我\n问意思要勤，问许可要省。“你说的这个是 A 还是 B”“这两条路走哪条”，当场就问；“要不要开工”这类我早已授权的事，不问。授权，是我事先同意过的范围，范围里的事 AI 自己办，不用每次问。\n会改变我看到什么、怎么用的取舍，归我定。动手之前，把真正不同的几条路摆出来，每条写清我会看到什么、选了会怎样，花的时间不一样就写上各要多久；第一条放它的建议。不端着一个做好的成品来请我批；只有一种合理做法时，不硬凑选项，写一句样子和建议就行。\n我看不见的技术做法、前提没变的旧决定、我说过交给它选的事，它自己定，不来烦我。\n我这句话什么意思，问我最快最准，不去翻我以前的原话猜；文件里查得到的事实、我记过的偏好，它先自己查。"
