      "imageText": "要我登录时只找一次，登好了自己关\n账号掉了登录，最麻烦的是没人发现：公开页面照样搜得到东西，AI 以为还登着，其实拿到的可能只是不登录也能看的那些；反过来，一个站一时打不开，也不该说成全都掉了线。所以“搜得到”不算“登着”，每个站登没登单独核：看站上只属于我的东西；账号编号只在网页里当场比，不带出来，也不存下来。\n找我也有分寸：要重新登录，先用存好的账号和自己收到的验证码登；登不了、要扫码或要我亲自过验证，才请〔网页跑腿〕把登录页开到我屏幕最前面，说一句“登一下”；我不在电脑边就不开页，记进实况、发个通知，先用别的来源交。没有查询在等，不开页催我；每周例行核出确实掉了的，在实况挂一条，等我方便时再登。\n实况里一个平台只留一条提醒，不会越积越多；提醒里写着怎么登，带一个直接跳过去的按钮。我登好以后不用回来报一声：程序重新核实站上确实是我，自己把提醒关掉。"
