      "imageText": "我照常用 Chrome，它在后台办\nAI 用的就是我天天在用的这个 Chrome，带着我在各个网站上的登录状态，不另开一个空白的浏览器。\n它跳转、点击、填写，都在自己新开的标签页里做，而且开在后台：Chrome 窗口顶上多出几个页签，却不切到我眼前，我正看着哪一页还是哪一页。我想看着它办，才拉到前台。\n我已经开着的页，它只读不动：不跳走、不刷新、不关，我写了一半还没交的内容原样留着。我点名让它用的那一页除外。\n网页上会另弹一个新页的链接，它先把地址取出来，放进自己的后台页里打开；取不到，就临时拦下这一次点击，看清它要去哪，马上恢复原样，网页上不留一点改动。\n它开的页用完就关，不把我的 Chrome 塞满；我自己的页，一个不关。"
