      "imageText": "能自己登的，自己登完\n要登录的网站，先找我已经登录着的那一页接着用。同一个 Chrome 里新开一页，有的网站会要求重新登录，原来那页却照样能用。\n要密码的，由一段自动程序去〔密码中心〕（我自己做的密码和私人资料保管程序）认准是哪个网站、哪个账号，取出密码直接填进核实过的那个网站的密码框。密码从头到尾不经过 AI 的眼睛，也不写进任何文件和运行记录。\n要手机号的，从〔我的说明书〕（记着我的背景、偏好和常用信息，AI 照着它懂我）里取我常用的号码，点“发送验证码”；短信、邮件里的验证码从已经接好的入口取回来，填上接着登。取验证码这门手艺在〔收信取码〕：短信和邮箱一起等，谁先到用谁。\n这些只用在我授权过（事先同意过的范围，范围里的事 AI 自己办，不用每次问）的账号上。取不到验证码，才请我自己填；短信那头没接通，就照实说没接通。\n要我自己扫码、按指纹或刷脸、在手机或别的设备上点同意，或者过人机验证（网站让人拖滑块、点图片，证明不是机器）的，就把这一步交给我亲手做。"
