        "几页都对得上：我开着好几页都对得上，先看清哪页是登录着的，点名选定一页再读，不随便拿第一页。",
        "读完存下什么：实际读到的标题、网址、正文，可选一张截图，是不是用了我开着的页，重试了几次，有没有超时、被取消。",
