      "imageText": "认内容，不认名字：同一份材料在云上只放一份\n按文件名认材料，会两头出错：同一张图挪了个文件夹、换了个用途，或者扩展名从 .PNG 写成 .png，就被当成新材料又传一遍；名字一个字没变、内容却改过了，又被当成老样子，AI 读到的还是旧稿。\n这里两头都按内容认：每次交给 AI 之前，都重新算一遍文件的校验码。内容一样，不管叫什么、放在哪、做什么用，云上都只有一份，网址照用；内容变了，哪怕名字没动，也传上新的一版，旧的那份标成“已被替换”，不再交出去。\n两件活同时要传同一份，也只传一次：先到的去传，后到的等它传完，直接用现成的。\n换新版只换这个文件在这件事上用的那一份；别的事还在用旧版的，照用不误。"
