      "imageText": "交一次，收一次：同一件活不重交、不重收\n云端看图这一路接通时，交出去的活超时了、没回音，顺手再交一遍最省事；可它也许早就交上了、正在云上干着，再交一遍，同一件活就被办了两回。\n这里每件活先在我电脑上写好一张单子，一张单子只交一次，拿到任务编号才算交上。没拿到编号，就先去核对交没交上，绝不自动再交。\n收结论的地方也只收一次，像一个只能投一次的信箱：每件活一个随机的长地址，里面先放一张“等结论”的空卡；结论交来时，要那张空卡还在才换得进去。两份同时交，只有一份换得进去；换进去以后空卡就没了，再来的，不管是重复交的，还是清理以后才赶到的迟到信，都投不进去，也不用一直记着谁交过。"
