        "这一门属于哪：〔AI 百工谱〕，我各家 AI 共用的一本规矩（写给 AI 的做事规定，各家 AI 读的是同一版）和一套手艺。",
        "出处是什么：每栏最后一条，写这一张讲的内容在项目里哪几份文件能对上。像 `skills/reply-as-me/SKILL.md`：SKILL.md 就是这份写给 AI 的做事说明，前面是它在项目里放的文件夹。",
