      "imageText": "它替我办成哪几件事\n要展开才说得清的汇报、要我拍板的事，AI 不在对话里堆一大段，做成一页本机网页（只在我这台电脑上打开的网页）：暖纸底、宋体标题，电脑、半屏、手机上都排得开，字号能调大。\n要我定的事做成题卡：附上真东西的样子，摆出几个选项，写清选了会怎样、各要多久；我点选、补一句说明，按一下就复制出完整答复，带回对话。汇报页上没有要我定的事，也得写一句为什么不用我定。\nAI 替我拿的主意一条条摆出来，我逐条表态，没表态的不算同意。\n要做页的分三种。大工程（我点名的，或 AI 估计要做满 6 小时、几个对话一起做）只开一页，地址不变，标题旁盖一枚“大工程”印；有新的先发手机通知，没看再发邮件；页上标着哪里新加、哪里改过、哪里我还没读；定过的要紧事一直留着，点开还看得到原题和全部选项；待定的多了分三级，每一级都能一键按 AI 建议选完。\n有题要我答的出普通答题页：打开到我眼前，就不在实况（我网站上的一页状态页，汇总有哪些事等我办）另摆一张，打不开才摆出来兜底。只要我知道的出普通汇报页，第一版就是定稿。三种叫我的办法各管一段，不重复叫。"
