      "imageText": "先约上，再排路线\n我选定以后，AI 先挑出要提前约、可能没票的，一样样列清：在哪约、要准备什么、几点放票、一般多久约满、去不了怎么退；多久约满说不准的写“待查”，不猜。\n要实名、要付钱的，我自己在手机上点，AI 不替我约。真约到了什么，它才照着排路线；约不上、时间撞了，就退回候选重选、重排。没约上的，计划上绝不写成“已约”。\n路线定死以后出图片版的计划：一天一张，左边是当天的路线地图，标着几点到哪；右边一项项列大概玩多久、走多少步；整天的景点拆细了列；另有花费单和每晚住哪的图。图上的字先由主持的 AI 写好，出图后逐张对，错了重出。画图交给〔画图改图〕，它把要的画面交给画图模型直接画。\n天气、营业时间、余票这些会变的，写明查什么、去哪查、什么时候查。\n再出一份手机上读的计划，开头写给手机上的 AI 看：先读计划，按我当时在哪、约到了什么来用，会变的到点再查。"
