      "imageText": "活派出去：断了能接，偏了能纠，验过才收\n主持是我直接对话、负责派活的那个 AI。它把一部分活交给另一个 AI 去做，接活的那个叫子代理。\n写单子：只写要得到什么、为什么要、什么不能动、怎么算做到，再定好最多写多少代码、给多少分钟；怎么做，由子代理自己查、自己定。\n派给谁：照〔新模型摸底〕定下的分工清单选，三家主持用同一张。成片施工直接交 Sol 牵头拆单、逐单验，主持定要什么、边界和验法；少数难事才先请 Astra 定方案。\n断了接着做：活由一个独立的后台程序（开着但不弹窗口、一直在后台跑的程序）带着跑；主持关掉了、断网了、子代理掉线了，都回到原来那段对话接着做，不从头再来。\n时限是闹钟：只算净干活的时间，到点叫醒主持看一眼，不一刀切断。\n半路纠正：一句话送进子代理正在做的活里，不叫停、不重来，看得到它听进去没有。\n盯一批不被骗：看的是成果有没有在长，不是程序还开不开着。\n验过才算交：干活的照真实用法跑一遍、交回原样结果，主持不重跑；成果一改就得重验。\n这几样怎么做到的，〔AI 百工谱〕项目页讲派活的那一张连着一整页细讲；〔AI 百工谱〕是我让各家 AI 共用的一套做事说明和工具。"
