      "imageText": "查错派三双眼睛：各看一样，互不知情\n写的人读自己的稿，脑子会顺手把漏掉的补上，怎么读都通顺。所以查文档、查图文，交给没看过稿子的新子代理，还把一句“帮我检查一下”拆成三种单子：\n对照单：只拿原件核一类东西，数字、日期、人名或引用。交回每一处在第几页、稿上怎么写、原件怎么写；看着怪又没依据的单列，只说哪里怪。\n读者单：当自己第一次看到它，只看这一份，不查别的文件。用自己的话说它要干什么、主张什么，再指出哪句有两种理解、哪句看不懂。复述出来的和本意对不上，就是没写清楚。\n挑刺单：告诉它写给谁、要达到什么、哪些是故意的，只找哪里说得太软、太像 AI，该说没说什么，对方最狠的反驳会打哪一句；不许它劝人加风险提示、免责声明、缓和语气。\n三种单子里都不放作者自己的看法，免得把它带偏；它只报看见了什么，不写改法、不评好坏。子代理看得准纸上写了什么，却没有主持手上的来龙去脉；所以事实错默认改，好不好、怎么改，由主持来定。"
